<section class="clientes-section" aria-label="Ecosistema e infraestructura tecnológica">
  <div class="container">
    <header class="stack-header">
      <div class="stack-badge">
        <span class="pulse-dot"></span>
        <span class="badge-label">Stack de Producción</span>
      </div>
      <p class="section-title">
        Tecnología seleccionada para alta disponibilidad, seguridad y rendimiento predecible.
      </p>
    </header>
    
    <!-- Track continuo de marquee sin saltos ni desbordamientos -->
    <div class="marquee-track">
      <div class="marquee-group">
        {#each stack as tech}
          <div class="tech-item" style="--hover-color: {tech.color}">
            <div class="tech-icon" aria-hidden="true">
              {@html tech.svg}
            </div>
            <div class="tech-text">
              <span class="tech-name">{tech.name}</span>
              <span class="tech-category">{tech.category}</span>
            </div>
          </div>
        {/each}
      </div>

      <!-- Duplicado exacto para bucle infinito suave -->
      <div class="marquee-group" aria-hidden="true">
        {#each stack as tech}
          <div class="tech-item" style="--hover-color: {tech.color}">
            <div class="tech-icon">
              {@html tech.svg}
            </div>
            <div class="tech-text">
              <span class="tech-name">{tech.name}</span>
              <span class="tech-category">{tech.category}</span>
            </div>
          </div>
        {/each}
      </div>
    </div>
  </div>
</section>

<style>
  .clientes-section {
    background-color: var(--color-background);
    padding: 4.5rem 1.5rem;
    border-bottom: 1px solid var(--color-border);
    border-top: 1px solid var(--color-border);
    overflow: hidden;
    position: relative;
    box-sizing: border-box;
    width: 100%;
    max-width: 100%;
    transition: background-color 0.3s ease, border-color 0.3s ease;
  }

  .container {
    max-width: 1200px;
    margin: 0 auto;
    width: 100%;
    box-sizing: border-box;
  }

  .stack-header {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    margin-bottom: 2.75rem;
  }

  .stack-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.35rem 0.95rem;
    border-radius: 9999px;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    box-shadow: var(--shadow-sm);
    margin-bottom: 0.9rem;
    transition: background-color 0.3s ease, border-color 0.3s ease;
  }

  .pulse-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background-color: var(--color-primary);
    box-shadow: 0 0 8px var(--color-primary);
    animation: dot-pulse 2s infinite ease-in-out;
  }

  @keyframes dot-pulse {
    0%, 100% {
      opacity: 1;
      transform: scale(1);
    }
    50% {
      opacity: 0.4;
      transform: scale(0.85);
    }
  }

  .badge-label {
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--color-text-secondary);
    letter-spacing: -0.01em;
  }

  .section-title {
    font-size: 1rem;
    line-height: 1.55;
    color: var(--color-text-primary);
    margin: 0;
    max-width: 58ch;
    text-wrap: pretty;
    font-weight: 600;
  }

  /* Marquee Track Continuo */
  .marquee-track {
    display: flex;
    overflow: hidden;
    position: relative;
    user-select: none;
    gap: 1.5rem;
    mask-image: linear-gradient(
      to right,
      rgba(0, 0, 0, 0) 0%,
      rgba(0, 0, 0, 1) 8%,
      rgba(0, 0, 0, 1) 92%,
      rgba(0, 0, 0, 0) 100%
    );
    -webkit-mask-image: linear-gradient(
      to right,
      rgba(0, 0, 0, 0) 0%,
      rgba(0, 0, 0, 1) 8%,
      rgba(0, 0, 0, 1) 92%,
      rgba(0, 0, 0, 0) 100%
    );
    padding: 0.5rem 0;
  }

  .marquee-group {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    gap: 1.5rem;
    min-width: 100%;
    animation: scroll-track 35s linear infinite;
    will-change: transform;
  }

  .marquee-track:hover .marquee-group {
    animation-play-state: paused;
  }

  .tech-item {
    display: inline-flex;
    align-items: center;
    gap: 0.95rem;
    padding: 0.75rem 1.35rem;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 14px;
    box-shadow: var(--shadow-sm);
    transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
    cursor: default;
    flex-shrink: 0;
  }

  .tech-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.25s ease;
  }

  .tech-text {
    display: flex;
    flex-direction: column;
    text-align: left;
  }

  .tech-name {
    font-size: 0.95rem;
    font-weight: 700;
    color: var(--color-text-primary);
    letter-spacing: -0.015em;
    transition: color 0.25s ease;
  }

  .tech-category {
    font-size: 0.74rem;
    color: var(--color-text-muted);
    font-weight: 500;
    margin-top: 0.1rem;
    font-variant-numeric: tabular-nums;
  }

  /* Hover micro-interactions */
  .tech-item:hover {
    background: var(--color-surface);
    border-color: var(--hover-color, var(--color-primary));
    transform: translateY(-3px);
    box-shadow: var(--shadow-md);
  }

  .tech-item:hover .tech-icon {
    transform: scale(1.12);
  }

  @keyframes scroll-track {
    from {
      transform: translateX(0);
    }
    to {
      transform: translateX(calc(-100% - 1.5rem));
    }
  }

  /* Accesibilidad: Reducción de movimiento */
  @media (prefers-reduced-motion: reduce) {
    .pulse-dot {
      animation: none;
    }
    .marquee-track {
      mask-image: none;
      -webkit-mask-image: none;
      overflow-x: hidden;
    }
    .marquee-group {
      animation: none;
      flex-wrap: wrap;
      justify-content: center;
      gap: 1rem;
    }
    .marquee-group[aria-hidden="true"] {
      display: none;
    }
  }

  @media (max-width: 640px) {
    .clientes-section {
      padding: 3rem 1rem;
    }
    .section-title {
      font-size: 0.92rem;
    }
    .tech-item {
      padding: 0.6rem 1.1rem;
    }
    .tech-name {
      font-size: 0.88rem;
    }
    .tech-category {
      font-size: 0.7rem;
    }
  }
</style>
